package com.orangehrm.UITests;

import com.orangehrm.pageobjects.LoginPage;
import org.testng.Assert;
import org.testng.annotations.DataProvider;
import org.testng.annotations.Test;

public class LoginTest extends BaseTest {

    private static final String ORANGEHRM_URL = "https://opensource-demo.orangehrmlive.com";

    @Test(dataProvider = "validCredentials", priority = 1, groups = {"smoke"})
    public void LoginToApp(String username, String password) {
        // navigate to app
        driver.navigate().to(ORANGEHRM_URL);

        // create login page object
        LoginPage loginPage = new LoginPage(driver);

        // verify login page is displayed
        Assert.assertTrue(loginPage.isLoginPageDisplayed(), "Login page should be displayed");

        // perform login
        loginPage.login(username, password);

        // wait and verify dashboard is loaded (wait for URL change or a dashboard element)
        driver.manage().timeouts().implicitlyWait(java.time.Duration.ofSeconds(5));

        // basic check: URL should not be login page anymore
        Assert.assertFalse(driver.getCurrentUrl().contains("login"), "Should not be on login page after successful login");
    }

    @Test(dataProvider = "invalidCredentials", priority = 2, groups = {"smoke"})
    public void LoginWithInvalidCredentials(String username, String password) {
        // navigate to app
        driver.navigate().to(ORANGEHRM_URL);

        // create login page object
        LoginPage loginPage = new LoginPage(driver);

        // verify login page is displayed
        Assert.assertTrue(loginPage.isLoginPageDisplayed(), "Login page should be displayed");

        // perform login with invalid credentials
        loginPage.login(username, password);

        // wait and verify user is still on login page (login should fail)
        driver.manage().timeouts().implicitlyWait(java.time.Duration.ofSeconds(3));

        // should still be on login page
        Assert.assertTrue(loginPage.isLoginPageDisplayed(), "Should remain on login page after failed login");
    }

    @DataProvider(name = "validCredentials")
    public Object[][] validCredentials() {
        return new Object[][] {
            {"Admin", "admin123"}
        };
    }

    @DataProvider(name = "invalidCredentials")
    public Object[][] invalidCredentials() {
        return new Object[][] {
            {"Admin1", "admin1234"},
            {"Admin2", "admin12345"}
        };
    }

}
